#pragma once
#include <Arduino.h>
#include <type_traits>
// Interface languages of the screens. English is written in the code as t("English"); the other languages come
// from include/I18nTable.h, generated by tools/i18n.py from i18n/firmware/<lang>.json. The language number is
// stored in NVS ("lang", Config.cpp), so the order below never changes; new languages go to the end.
enum Lang : uint8_t {
  LangEn,
  LangUk,
  LangEs,
  LangPt,
  LangFr,
  LangDe,
  LangIt,
  LangPl,
  LangTr,
  LangZh,
  LangJa,
  LangKo,
  LangAr,
  LangId,
  LangCount
};
extern const char* const langCodes[LangCount]; // "en", "uk", ...
extern const char* const langNames[LangCount]; // each in its own language
int langFromCode(const String& code); // -1 when unknown
bool langAvailable(uint8_t l);
uint8_t langStep(uint8_t l, int dir); // the next (dir>0) or previous available language
// The text in the interface language; a string without a translation shows English. tr("English") is a macro: the
// key of the translation (FNV-1a over the English text, as tools/i18n.py) is computed by the compiler. Strings read
// from tables at run time go through trText(), which hashes them then.
constexpr uint32_t i18nFnv(const char* s, uint32_t h) {
  while (*s) h = (h ^ uint8_t(*s++)) * 0x01000193u;
  return h;
}
constexpr uint32_t i18nKey(const char* en) {
  return i18nFnv(en, 0x811c9dc5u);
}
const char* trKey(const char* en, uint32_t key);
inline const char* trText(const char* en) {
  return trKey(en, i18nKey(en));
}
#define tr(en) trKey(en, std::integral_constant<uint32_t, i18nKey(en)>::value)
// Marks a string in a table for tools/i18n.py; it is translated where it is read, with trText().
#define N_(en) en
// "5 games": the number and the noun form its language needs. English is the argument (number, space, form);
// translations place the number with {n} or leave it out.
String plural(unsigned n, const char* one, const char* many);

// Drawing text in every language.
// Arabic is joined (presentation forms) and put in visual order; other text comes back unchanged.
String visualText(const String& logical);
// Fonts tried after `font` for a glyph it lacks: Latin-1, Latin Extended, then the CJK and Arabic subsets
// (include/I18nFonts.h), the interface language's script first. Null-terminated.
const uint8_t* const* fallbackFonts(const uint8_t* font);
bool fontHasGlyph(const uint8_t* font, uint16_t cp);
// Two cells for CJK and other wide glyphs, one otherwise: column counting on the 128x64 screens.
uint8_t glyphCells(uint32_t cp);
uint32_t utf8Next(const String& s, unsigned& i); // the codepoint at i; i moves past it
